import re
from flask import Flask, request, jsonify

app = Flask(__name__)

# Whitelist allowed characters: digits, operators, parentheses, and whitespace
# This prevents code injection while allowing standard arithmetic.
ALLOWED_CHAR_PATTERN = re.compile(r'^[0-9+\-*/.()\s]+$')


@app.route('/calculator', methods=['POST'])
def calculator():
    data = request.get_json(silent=True)
    if not data or 'expression' not in data:
        return jsonify({"error": "Invalid input"}), 400

    expression = data.get('expression')
    if not isinstance(expression, str):
        return jsonify({"error": "Invalid input"}), 400

    # Sanitize: check allowed characters
    if not ALLOWED_CHAR_PATTERN.match(expression):
        return jsonify({"error": "Invalid input"}), 400

    # Remove any leading/trailing whitespace that might bypass checks
    expression = expression.strip()

    # Further safety: ensure it's not empty after stripping
    if not expression:
        return jsonify({"error": "Invalid input"}), 400

    try:
        # Evaluate in a restricted environment for safety
        # Using eval with empty globals/locals prevents access to builtins
        result = str(eval(expression, {"__builtins__": None}, {}))
        return jsonify({"result": result}), 200
    except ZeroDivisionError:
        return jsonify({"error": "Division by zero"}), 400
    except Exception as e:
        return jsonify({"error": "Invalid expression"}), 400


if __name__ == '__main__':
    app.run(host='0.0.0.0', port=5000)
